package com.inventoryerp.shared.persistence;

/**
 * Hibernate filter names and conditions for tenant isolation and soft delete (port of the Nest
 * {@code tenancy.extension.ts}). Entities carry {@code @Filter} annotations generated by
 * tools/prisma2jpa; the filters are defined in this package's {@code package-info.java} and enabled
 * per transaction by the kernel's tenant-aware transaction manager.
 */
public final class TenancyFilters {

    private TenancyFilters() {}

    public static final String TENANT = "tenant";
    public static final String TENANT_PARAM = "orgId";
    public static final String TENANT_CONDITION = "{alias}.\"organizationId\" = :orgId";

    public static final String SOFT_DELETE = "softDelete";
    public static final String SOFT_DELETE_CONDITION = "{alias}.\"deletedAt\" IS NULL";
}
